package parsers

import (
	"github.com/azusachino/iroha/apps/iroha-core/i18n"
	"github.com/azusachino/iroha/apps/iroha-core/observations"
)

// appleHealthProvider is the provider key both Apple ingestion paths write.
// Health Auto Export posts workouts recorded by an Apple Watch and the native
// export is generated by the same device, so both share one canonical activity
// identity.
const appleHealthProvider = "apple_health"

// resolveProviderActivity reads a provider activity label through the shared
// i18n activity taxonomy and returns the canonical sport slug, title, and the
// title's provenance.
//
// System labels — Health Auto Export's names, which Apple localizes to the
// device's iOS locale, and the native export's HKWorkoutActivityType enums —
// resolve to universal English canonicals, so a run recorded while iOS was
// Japanese still lands on "Outdoor Run". Labels the taxonomy does not own keep
// the provider's own text (with the HealthKit enum prefix stripped) and a
// provider-specific slug, so an unmapped sport is never flattened into "other"
// or loses its title; those are recorded as custom titles.
func resolveProviderActivity(label string, ctx i18n.ActivityContext) (sportType string, title string, titleOrigin string) {
	classification := i18n.ResolveActivity(label, ctx)
	if classification.IsSystemLabel {
		return classification.SportType, classification.CanonicalTitle, observations.TitleOriginSystem
	}
	return observations.NormalizeSport(label), i18n.TrimAppleHealthActivityTypePrefix(label), observations.TitleOriginCustom
}
